package redis

import (
	"context"
	"fmt"
	"slices"
	"sync"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/redis/go-redis/v9"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/e2b-dev/infra/packages/api/internal/sandbox/sandboxtypes"
)

// mgetRecorder is a go-redis hook that records the key count of every MGET the
// client sends, including MGETs inside pipelines.
type mgetRecorder struct {
	mu        sync.Mutex
	keyCounts []int
}

func (r *mgetRecorder) record(cmd redis.Cmder) {
	if cmd.Name() != "mget" {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	// args = ["mget", key1, key2, ...]
	r.keyCounts = append(r.keyCounts, len(cmd.Args())-1)
}

func (r *mgetRecorder) reset() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.keyCounts = nil
}

func (r *mgetRecorder) snapshot() []int {
	r.mu.Lock()
	defer r.mu.Unlock()

	return append([]int(nil), r.keyCounts...)
}

func (r *mgetRecorder) DialHook(next redis.DialHook) redis.DialHook {
	return next
}

func (r *mgetRecorder) ProcessHook(next redis.ProcessHook) redis.ProcessHook {
	return func(ctx context.Context, cmd redis.Cmder) error {
		r.record(cmd)

		return next(ctx, cmd)
	}
}

func (r *mgetRecorder) ProcessPipelineHook(next redis.ProcessPipelineHook) redis.ProcessPipelineHook {
	return func(ctx context.Context, cmds []redis.Cmder) error {
		for _, cmd := range cmds {
			r.record(cmd)
		}

		return next(ctx, cmds)
	}
}

// TestReconcile_SpansSeveralBatches pins that Reconcile classifies every node
// sandbox correctly when one team's candidates are split across several MGET
// commands: each result has to line up with the candidate it was fetched for,
// or a live sandbox in one chunk would be reported as an orphan from another.
//
// It also asserts the chunking itself through a client hook: the number of
// MGETs sent, that none carries more than sandboxScanBatchSize keys, and that
// the key counts add up to the candidate count. The orphan-set check alone
// passes with a single unbounded MGET, so without this a revert of the
// chunking would go unnoticed.
func TestReconcile_SpansSeveralBatches(t *testing.T) {
	t.Parallel()

	storage, client := setupTestStorage(t)
	teamID := uuid.New()
	started := time.Now().Add(-2 * orphanGracePeriod)

	rec := &mgetRecorder{}
	client.AddHook(rec)

	// More than two full chunks plus a partial one, all in the store.
	stored := sandboxScanBatchSize*2 + 37
	seedTeamSandboxes(t, client, teamID, stored, sandboxtypes.StateRunning)

	var nodeSandboxes []sandboxtypes.NodeSandbox
	for i := range stored {
		nodeSandboxes = append(nodeSandboxes, sandboxtypes.NodeSandbox{
			SandboxID: fmt.Sprintf("sbx-%s-%04d", sandboxtypes.StateRunning, i),
			TeamID:    teamID,
			StartTime: started,
		})
	}

	// Orphans the node reports but the store never saw, placed so that they
	// land in the first, a middle, and the final chunk.
	orphanIDs := []string{"orphan-first", "orphan-middle", "orphan-last"}
	orphans := []sandboxtypes.NodeSandbox{
		{SandboxID: orphanIDs[0], TeamID: teamID, StartTime: started},
		{SandboxID: orphanIDs[1], TeamID: teamID, StartTime: started},
		{SandboxID: orphanIDs[2], TeamID: teamID, StartTime: started},
	}
	nodeSandboxes = slices.Insert(nodeSandboxes, 0, orphans[0])
	nodeSandboxes = slices.Insert(nodeSandboxes, sandboxScanBatchSize+10, orphans[1])
	nodeSandboxes = append(nodeSandboxes, orphans[2])

	// Too young to be judged, even though it is not in the store.
	nodeSandboxes = append(nodeSandboxes, sandboxtypes.NodeSandbox{
		SandboxID: "fresh-not-yet-stored",
		TeamID:    teamID,
		StartTime: time.Now(),
	})

	// Seeding does not MGET, but reset so the assertions below see only what
	// Reconcile sent.
	rec.reset()

	got := storage.Reconcile(t.Context(), nodeSandboxes, "test-node")

	gotIDs := make([]string, 0, len(got))
	for _, sbx := range got {
		gotIDs = append(gotIDs, sbx.SandboxID)
	}
	require.ElementsMatch(t, orphanIDs, gotIDs, "exactly the stored-nowhere, old-enough sandboxes are orphans")
	for _, sbx := range got {
		assert.Equal(t, teamID, sbx.TeamID)
	}

	// Candidates = stored + 3 orphans; the fresh one is filtered before any
	// read. 552 keys / 256 per command = 3 commands: 256, 256, 40.
	candidates := stored + len(orphans)
	counts := rec.snapshot()
	wantCmds := (candidates + sandboxScanBatchSize - 1) / sandboxScanBatchSize
	require.Len(t, counts, wantCmds, "MGET commands sent: %v", counts)
	sum := 0
	for _, n := range counts {
		require.LessOrEqual(t, n, sandboxScanBatchSize, "an MGET exceeded the per-command key cap: %v", counts)
		sum += n
	}
	require.Equal(t, candidates, sum, "MGET key counts should cover every candidate exactly once: %v", counts)
}

package setup

import (
	"context"
	"net/http"

	"github.com/e2b-dev/infra/tests/integration/internal/api"
)

func GetAPIClient() *api.ClientWithResponses {
	hc := http.Client{
		Timeout: apiTimeout,
	}

	c, err := api.NewClientWithResponses(APIServerURL, api.WithHTTPClient(&hc))
	if err != nil {
		panic(err)
	}

	return c
}

func WithAPIKey(apiKey ...string) func(ctx context.Context, req *http.Request) error {
	return func(_ context.Context, req *http.Request) error {
		apiKey_ := APIKey
		if len(apiKey) > 0 {
			apiKey_ = apiKey[0]
		}
		req.Header.Set("X-API-Key", apiKey_)

		return nil
	}
}

func WithTestsUserAgent() api.RequestEditorFn {
	return WithUserAgent("e2b-tests/infra")
}

func WithUserAgent(userAgent string) api.RequestEditorFn {
	return func(_ context.Context, req *http.Request) error {
		req.Header.Set("User-Agent", userAgent)

		return nil
	}
}

func WithTeamID(teamID ...string) func(ctx context.Context, req *http.Request) error {
	teamID_ := TeamID
	if len(teamID) > 0 {
		teamID_ = teamID[0]
	}

	return func(_ context.Context, req *http.Request) error {
		req.Header.Set("X-Team-ID", teamID_)

		return nil
	}
}

package handlers

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/gin-gonic/gin"
)

func TestPostAdminTeamsBootstrapAlwaysFails(t *testing.T) {
	t.Parallel()

	recorder := httptest.NewRecorder()
	ginCtx, _ := gin.CreateTestContext(recorder)
	ginCtx.Request = httptest.NewRequestWithContext(t.Context(), http.MethodPost, "/admin/teams/bootstrap", strings.NewReader(`{
		"name": "Bootstrap team",
		"email": "bootstrap-team@example.com"
	}`))
	ginCtx.Request.Header.Set("Content-Type", "application/json")

	store := &APIStore{}
	store.PostAdminTeamsBootstrap(ginCtx)

	if recorder.Code != http.StatusInternalServerError {
		t.Fatalf("expected status 500, got %d: %s", recorder.Code, recorder.Body.String())
	}
	if !strings.Contains(recorder.Body.String(), retiredBootstrapMessage) {
		t.Fatalf("expected retired-operation message, got %s", recorder.Body.String())
	}
}

package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// The two secrets middlewares are exercised end to end, in the order the API
// composes them, by the confidentiality tests in the handlers package - that is
// where the matched-route half of this predicate is proven. Here it is checked
// for the requests no route matches, which reach it by path alone and must be
// treated just as confidentially.
func TestIsSecretsRouteByPath(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		path string
		want bool
	}{
		{name: "family root", path: "/secrets", want: true},
		{name: "selector", path: "/secrets/my-secret", want: true},
		{name: "unknown sub path", path: "/secrets/my-secret/versions", want: true},
		{name: "another route sharing the prefix", path: "/secretsomething", want: false},
		{name: "unrelated route", path: "/volumes", want: false},
		{name: "root", path: "/", want: false},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			c, _ := gin.CreateTestContext(httptest.NewRecorder())
			c.Request = httptest.NewRequestWithContext(t.Context(), http.MethodGet, test.path, nil)

			assert.Equal(t, test.want, IsSecretsRoute(c))
		})
	}
}

func TestNoStoreSecretsMarksEveryEngineResponse(t *testing.T) {
	t.Parallel()

	engine := gin.New()
	engine.RedirectTrailingSlash = false
	engine.Use(NoStoreSecrets())
	engine.GET("/secrets", func(c *gin.Context) { c.Status(http.StatusNoContent) })
	engine.GET("/secrets/:secretID", func(c *gin.Context) { c.Status(http.StatusNoContent) })
	engine.GET("/volumes", func(c *gin.Context) { c.Status(http.StatusNoContent) })

	tests := []struct {
		name        string
		path        string
		wantStatus  int
		wantNoStore bool
	}{
		{name: "family root", path: "/secrets", wantStatus: http.StatusNoContent, wantNoStore: true},
		{name: "selector", path: "/secrets/my-secret", wantStatus: http.StatusNoContent, wantNoStore: true},
		{name: "unmatched descendant 404", path: "/secrets/my-secret/versions", wantStatus: http.StatusNotFound, wantNoStore: true},
		{name: "shared prefix only", path: "/secretsfoo", wantStatus: http.StatusNotFound},
		{name: "unrelated route", path: "/volumes", wantStatus: http.StatusNoContent},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			request := httptest.NewRequestWithContext(t.Context(), http.MethodGet, test.path, nil)
			recorder := httptest.NewRecorder()
			engine.ServeHTTP(recorder, request)

			require.Equal(t, test.wantStatus, recorder.Code)
			if test.wantNoStore {
				assert.Equal(t, []string{cacheControlNoStoreValue}, recorder.Header().Values(cacheControlHeader))
			} else {
				assert.Empty(t, recorder.Header().Values(cacheControlHeader))
			}
		})
	}
}

package utils

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// A template build start body can carry the caller's private registry
// credentials. A request the spec rejects must not put them in the response or
// in the errors it records, since those reach the access log and the span.
func TestRejectedTemplateBuildNeverRevealsRegistryCredentials(t *testing.T) {
	t.Parallel()

	const (
		secret = "registry-secret-DO-NOT-LOG"
		target = "/v2/templates/tpl/builds/00000000-0000-0000-0000-000000000000"
	)

	registries := map[string]string{
		"registry": `{"type":"registry","username":"user","password":"` + secret + `"}`,
		"aws":      `{"type":"aws","awsAccessKeyId":"id","awsSecretAccessKey":"` + secret + `","awsRegion":"us-east-1"}`,
		"gcp":      `{"type":"gcp","serviceAccountJson":"` + secret + `"}`,
	}
	rejections := map[string]func(registry string) string{
		"malformed files hash": func(registry string) string {
			return `{"fromImage":"alpine","fromImageRegistry":` + registry + `,"steps":[{"type":"COPY","filesHash":""}]}`
		},
		"empty fromImage": func(registry string) string {
			return `{"fromImage":"","fromImageRegistry":` + registry + `}`
		},
		"malformed force": func(registry string) string {
			return `{"fromImage":"alpine","fromImageRegistry":` + registry + `,"force":"yes"}`
		},
	}

	for registryName, registry := range registries {
		for rejectionName, body := range rejections {
			t.Run(registryName+"/"+rejectionName, func(t *testing.T) {
				t.Parallel()

				assertRejectedWithoutSecret(t, target, body(registry), secret)
			})
		}
	}

	t.Run("malformed registry", func(t *testing.T) {
		t.Parallel()

		assertRejectedWithoutSecret(t, target,
			`{"fromImage":"alpine","fromImageRegistry":{"type":"registry","password":"`+secret+`"}}`, secret)
	})
}

func assertRejectedWithoutSecret(t *testing.T, target, body, secret string) {
	t.Helper()

	router, recorded := newValidatingRouter(t)

	request := httptest.NewRequestWithContext(t.Context(), http.MethodPost, target, strings.NewReader(body))
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("X-API-Key", "e2b_key")

	recorder := httptest.NewRecorder()
	router.ServeHTTP(recorder, request)

	require.Equal(t, http.StatusBadRequest, recorder.Code, recorder.Body.String())
	assert.NotContains(t, recorder.Body.String(), secret, "the response echoed a registry credential")

	require.NotEmpty(t, *recorded, "the rejection was not recorded at all")
	for _, err := range *recorded {
		assert.NotContains(t, err.Error(), secret, "a recorded error carried a registry credential")
	}
}

package utils

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/getkin/kin-openapi/openapi3filter"
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	middleware "github.com/oapi-codegen/gin-middleware"
	"github.com/stretchr/testify/require"

	"github.com/e2b-dev/infra/packages/api/internal/api"
	"github.com/e2b-dev/infra/packages/auth/pkg/auth"
	"github.com/e2b-dev/infra/packages/auth/pkg/types"
)

func TestAdminJWTAlternativePreservesAdminTeamFailureStatus(t *testing.T) {
	t.Parallel()

	swagger, err := api.GetSpec()
	require.NoError(t, err)
	swagger.Servers = nil

	authenticationFunc := auth.CreateAuthenticationFunc(
		[]auth.Authenticator{
			auth.NewApiKeyAuthenticator(func(context.Context, *gin.Context, string) (*types.Team, *auth.APIError) {
				return nil, nil
			}),
			auth.NewAuthProviderBearerAuthenticator(func(context.Context, *gin.Context, string) (uuid.UUID, *auth.APIError) {
				return uuid.Nil, nil
			}),
			auth.NewAuthProviderTeamAuthenticator(func(context.Context, *gin.Context, string) (*types.Team, *auth.APIError) {
				return nil, nil
			}),
			auth.NewAdminApiKeyAuthenticator("admin-token"),
			auth.NewAdminJWTAuthenticator(nil),
			auth.NewAdminTeamAuthenticator(func(context.Context, *gin.Context, string) (*types.Team, *auth.APIError) {
				return nil, &auth.APIError{
					Code:      http.StatusNotFound,
					Err:       errors.New("team not found"),
					ClientMsg: "Team not found",
				}
			}),
		},
		nil,
	)

	r := gin.New()
	r.Use(middleware.OapiRequestValidatorWithOptions(swagger, &middleware.Options{
		ErrorHandler: func(c *gin.Context, message string, fallbackStatusCode int) {
			statusCode := max(c.Writer.Status(), fallbackStatusCode)
			ErrorHandler(c, message, statusCode)
		},
		MultiErrorHandler: MultiErrorHandler,
		Options: openapi3filter.Options{
			AuthenticationFunc: authenticationFunc,
			MultiError:         true,
		},
		SilenceServersWarning: true,
	}))
	r.GET("/api-keys", func(c *gin.Context) {
		c.Status(http.StatusOK)
	})

	req := httptest.NewRequestWithContext(t.Context(), http.MethodGet, "/api-keys", nil)
	req.Header.Set(auth.HeaderAdminToken, "admin-token")
	req.Header.Set(auth.HeaderTeamID, "unknown-team")
	rr := httptest.NewRecorder()
	r.ServeHTTP(rr, req)

	require.Equal(t, http.StatusNotFound, rr.Code)
	require.Contains(t, rr.Body.String(), "Team not found")
}

package utils

import (
	"context"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/getkin/kin-openapi/openapi3filter"
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	middleware "github.com/oapi-codegen/gin-middleware"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/e2b-dev/infra/packages/api/internal/api"
	"github.com/e2b-dev/infra/packages/auth/pkg/auth"
	"github.com/e2b-dev/infra/packages/auth/pkg/types"
)

// A webhook create or update body carries the caller's signing secret, which
// is enough to forge a delivery for that team. This drives the real spec and
// the real validator, because what a rejected request reveals is decided by
// the layers together: the validator's message, the multi-error selection, and
// the error handler. The errors it records are checked alongside the response,
// since those are what reach the access log and the span.
func TestRejectedWebhookRequestNeverRevealsTheSigningSecret(t *testing.T) {
	t.Parallel()

	const secret = "whsec-DO-NOT-LOG-0000"

	for _, test := range []struct {
		name   string
		method string
		target string
		body   string
	}{
		{
			name: "create missing every other required field",
			// The failure is at the root, so the validator reports the object
			// it refused rather than one field of it.
			method: http.MethodPost, target: "/events/webhooks",
			body: `{"signatureSecret":"` + secret + `"}`,
		},
		{
			name:   "create with a malformed field",
			method: http.MethodPost, target: "/events/webhooks",
			body: `{"name":"alerts","url":"https://example.com","events":"not-a-list","signatureSecret":"` + secret + `"}`,
		},
		{
			name:   "update with a malformed field",
			method: http.MethodPatch, target: "/events/webhooks/" + uuid.NewString(),
			body: `{"enabled":"yes","signatureSecret":"` + secret + `"}`,
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			router, recorded := newValidatingRouter(t)

			request := httptest.NewRequestWithContext(t.Context(), test.method, test.target, strings.NewReader(test.body))
			request.Header.Set("Content-Type", "application/json")
			request.Header.Set("X-API-Key", "e2b_key")

			recorder := httptest.NewRecorder()
			router.ServeHTTP(recorder, request)

			require.Equal(t, http.StatusBadRequest, recorder.Code, recorder.Body.String())
			assert.NotContains(t, recorder.Body.String(), secret, "the response echoed the signing secret")

			require.NotEmpty(t, *recorded, "the rejection was not recorded at all")
			for _, err := range *recorded {
				assert.NotContains(t, err.Error(), secret, "a recorded error carried the signing secret")
			}
		})
	}
}

// newValidatingRouter serves the spec's own request validation, authenticating
// every caller, and returns the errors each request recorded. The webhook and
// template build routes are registered so a rejected request is answered by the
// validator rather than by gin's own not-found.
func newValidatingRouter(t *testing.T) (*gin.Engine, *[]error) {
	t.Helper()

	swagger, err := api.GetSpec()
	require.NoError(t, err)
	swagger.Servers = nil

	authenticationFunc := auth.CreateAuthenticationFunc(
		[]auth.Authenticator{
			auth.NewApiKeyAuthenticator(func(context.Context, *gin.Context, string) (*types.Team, *auth.APIError) {
				return &types.Team{}, nil
			}),
		},
		nil,
	)

	recorded := &[]error{}

	router := gin.New()
	router.Use(func(c *gin.Context) {
		c.Next()

		for _, ginErr := range c.Errors {
			*recorded = append(*recorded, ginErr)
		}
	})
	router.Use(middleware.OapiRequestValidatorWithOptions(swagger, &middleware.Options{
		ErrorHandler: func(c *gin.Context, message string, fallbackStatusCode int) {
			ErrorHandler(c, message, max(c.Writer.Status(), fallbackStatusCode))
		},
		MultiErrorHandler: MultiErrorHandler,
		Options: openapi3filter.Options{
			AuthenticationFunc: authenticationFunc,
			MultiError:         true,
		},
		SilenceServersWarning: true,
	}))

	reached := func(c *gin.Context) { c.Status(http.StatusOK) }
	router.POST("/events/webhooks", reached)
	router.PATCH("/events/webhooks/:webhookID", reached)
	router.POST("/v2/templates/:templateID/builds/:buildID", reached)

	return router, recorded
}

package oauth

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/require"
	"google.golang.org/grpc/metadata"

	proxygrpc "github.com/e2b-dev/infra/packages/shared/pkg/grpc/proxy"
)

func TestNewVerifierConfig(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name      string
		issuerURL string
	}{
		{
			name: "empty config returns noop verifier",
		},
		{
			name:      "trims empty config",
			issuerURL: " ",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			verifier, err := NewVerifier(t.Context(), tt.issuerURL)
			require.NoError(t, err)
			require.NotNil(t, verifier)
		})
	}
}

func TestNoopVerifierRejectsClaims(t *testing.T) {
	t.Parallel()

	verifier, err := NewVerifier(t.Context(), "")
	require.NoError(t, err)

	claims, err := verifier.VerifyClaims(t.Context(), "token")
	require.Error(t, err)
	require.Empty(t, claims)
}

func TestNewVerifierLoadsOIDCProvider(t *testing.T) {
	t.Parallel()

	issuerURL := ""
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/.well-known/openid-configuration":
			writeJSON(t, w, map[string]string{
				"issuer":   issuerURL,
				"jwks_uri": issuerURL + "/jwks",
			})
		case "/jwks":
			writeJSON(t, w, map[string]any{"keys": []any{}})
		default:
			http.NotFound(w, r)
		}
	}))
	t.Cleanup(server.Close)
	issuerURL = server.URL

	verifier, err := NewVerifier(t.Context(), server.URL)
	require.NoError(t, err)
	require.NotNil(t, verifier)
}

func writeJSON(t *testing.T, w http.ResponseWriter, value any) {
	t.Helper()

	w.Header().Set("Content-Type", "application/json")
	require.NoError(t, json.NewEncoder(w).Encode(value))
}

type fakeVerifier struct {
	claims Claims
	err    error
}

func (v fakeVerifier) VerifyClaims(context.Context, string) (Claims, error) {
	return v.claims, v.err
}

func TestRequireBearerToken(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name      string
		md        metadata.MD
		wantToken string
		wantErr   bool
	}{
		{
			name:    "missing authorization",
			md:      metadata.MD{},
			wantErr: true,
		},
		{
			name:    "malformed authorization",
			md:      metadata.Pairs(proxygrpc.MetadataAuthorization, "token"),
			wantErr: true,
		},
		{
			name:    "empty bearer token",
			md:      metadata.Pairs(proxygrpc.MetadataAuthorization, "Bearer "),
			wantErr: true,
		},
		{
			name:      "bearer token",
			md:        metadata.Pairs(proxygrpc.MetadataAuthorization, "Bearer token"),
			wantToken: "token",
		},
	}

