func TestRefusalBackoff_WindowDoublesUpToCap(t *testing.T) {
	t.Parallel()

	b := refusalBackoff{base: 25 * time.Millisecond, max: time.Second}

	tests := []struct {
		refusals int
		want     time.Duration
	}{
		{0, 0},
		{1, 25 * time.Millisecond},
		{2, 50 * time.Millisecond},
		{3, 100 * time.Millisecond},
		{6, 800 * time.Millisecond},
		{7, time.Second},
